        "section": "typography"
      },
      {
        "name": "The One-Lift Rule",
        "body": "At most one lifted panel per screen. Nested bordered summaries inside, never nested lifted cards.",
        "section": "elevation"
      }
    ],
    "dos": [
      "Do keep the donor path obvious on mobile: preset amounts, large tap targets, QRIS instructions in numbered steps.",
